120	export const useMonitoringFiltersTimeRange = () => {
121	  const [monitoringFilters] = useMonitoringFilters({
122	    loadPersistedValues: shouldEnableTracesTableStatePersistence(),
123	  });
124	
125	  return useMemo(() => {
126	    const { startTime, endTime } = monitoringFilters;
127	    return {
128	      startTime: startTime ? new Date(startTime).getTime().toString() : undefined,
129	      endTime: endTime ? new Date(endTime).getTime().toString() : undefined,
130	    };
131	  }, [monitoringFilters]);
132	};
