// page tabs and should be preserved when navigating between any tabs, regardless of tab group.
// All other params are considered tab-specific and are only preserved within their tab group.
const TIME_RANGE_QUERY_PARAM_KEYS = [START_TIME_LABEL_QUERY_PARAM_KEY, 'startTime', 'endTime'];

/**
 * Computes the `search` (query string) to use for a side nav link, given the current URL search
 * string, the currently active tab, and the tab the link navigates to.
 *
 * - When navigating between two traces-related tabs, ALL current query params are preserved
 *   (both time range params and traces-specific params such as selectedTraceId).
 * - Otherwise, only the time range params (e.g. startTimeLabel, startTime) are preserved and all
 *   other tab-specific params (e.g. selectedTraceId, selectedDatasetId, viewMode) are dropped.
 *
 * Returns `undefined` when there are no params to preserve.
 */
export const getSideNavLinkSearch = (
  search: string,
  activeTab: ExperimentPageTabName,
  targetTab: ExperimentPageTabName,
): string | undefined => {
  const preserveAllParams = isTracesRelatedTab(activeTab) && isTracesRelatedTab(targetTab);
  if (preserveAllParams) {
    return search || undefined;
  }

  const currentParams = new URLSearchParams(search);
  const preservedParams = new URLSearchParams();
  for (const key of TIME_RANGE_QUERY_PARAM_KEYS) {
    for (const value of currentParams.getAll(key)) {
      preservedParams.append(key, value);
    }
  }

  const preservedSearch = preservedParams.toString();
  return preservedSearch ? `?${preservedSearch}` : undefined;
};
